-- 15B.13C: source-grounded S02 I10 correction; system-authored content migration.
-- Whole-bank audit: docs/chapter-ii-s02-whole-bank-review.md.
-- No schema/runtime/auth changes; old versions/reviews and learner records are immutable here.
do $revision$
declare
  v_item public.items%rowtype;
  v_template public.item_templates%rowtype;
  v_corpus jsonb;
  v_new_misconception uuid;
begin
  select * into strict v_item from public.items where code='PHY7-U02-S02-I10';
  -- Same family lock used by ordinary governed revisions and atomic approval.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_item.item_template_id::text,1508001));
  perform 1 from public.items where skill_id=v_item.skill_id order by code for update;
  select * into strict v_item from public.items where id=v_item.id;
  select * into strict v_template from public.item_templates where id=v_item.item_template_id for update;
  perform 1 from public.curriculum_releases where release_key='physics7_u01_u02_2026_08_14_candidate_r2' for update;
  if not exists(select 1 from public.curriculum_releases where release_key='physics7_u01_u02_2026_08_14_candidate_r2' and status='draft') then
    raise exception '15B13C_candidate_not_draft';
  end if;
  if v_item.version_no<>1 or v_item.status<>'published' or v_item.review_status<>'approved'
      or v_item.retired_at is not null or v_item.prompt_hy<>'Նկարում պատկերված պղնձե լարը տաքացնելիս երկարում է։ Մեկ այլ փորձով փակ ներարկիչի օդը սեղմում են՝ առանց օդի արտահոսքի։ Ո՞ր զույգ բացատրությունն է համապատասխանում երկու փորձերին՝ պարզ մասնիկային մոդելի շրջանակում։'
      or v_template.template_version<>1 or v_template.code<>'PHY7-U02-S02-T03-PARTICLE-MODEL-LIMITS' then
    raise exception '15B13C_current_revision_changed';
  end if;
  select jsonb_agg(jsonb_build_object('code',i.code,'version',i.version_no,'prompt',i.prompt_hy,
    'options',(select jsonb_agg(jsonb_build_object('key',o.option_key,'text',o.content_hy) order by o.display_order) from public.item_options o where o.item_id=i.id),
    'answer',(select k.answer from public.item_answer_keys k where k.item_id=i.id),'stimulus',i.stimulus) order by i.code)
  into v_corpus from public.items i where i.skill_id=v_item.skill_id;
  if v_corpus is distinct from '[{"code":"PHY7-U02-S02-I01","version":2,"prompt":"Ջրով լի բաժակի մեջ մեկ թեյի գդալ աղ են լուծում, բայց ջուրը բաժակից չի թափվում։ Ո՞ր եզրակացությունն է լավագույնս բացատրում դիտումը։","options":[{"key":"A","text":"Աղը լուծվելիս ամբողջությամբ անհետանում է և այլևս նյութ չէ։"},{"key":"B","text":"Ջրի մասնիկների միջև կան ազատ տարածություններ, որոնցում տեղավորվում են աղի մասնիկները։"},{"key":"C","text":"Լուծվելիս ջրի զանգվածը փոքրանում է։"},{"key":"D","text":"Աղի մասնիկները վերածվում են ջրի մասնիկների։"}],"answer":"B","stimulus":{}},{"code":"PHY7-U02-S02-I02","version":2,"prompt":"Մեկ լիտր ջուրը խառնում են մեկ լիտր սպիրտի հետ, սակայն խառնուրդի ծավալը 2 լիտրից փոքր է։ Ո՞ր բացատրությունն է համապատասխանում նյութի մասնիկային կառուցվածքին։","options":[{"key":"A","text":"Մասնիկների մի մասը ոչնչանում է։"},{"key":"B","text":"Խառնելիս հեղուկների զանգվածը անհետանում է։"},{"key":"C","text":"Մի նյութի մասնիկները տեղավորվում են մյուս նյութի մասնիկների միջև եղած ազատ տարածություններում։"},{"key":"D","text":"Ջուրն ու սպիրտը հոծ են և մասնիկներ չունեն։"}],"answer":"C","stimulus":{}},{"code":"PHY7-U02-S02-I03","version":4,"prompt":"Որոշ գազեր բարձր ջերմաստիճանում կարող են անցնել երկաթե պատի միջով։ Ո՞ր եզրակացությանն է աջակցում այս դիտարկումը։","options":[{"key":"A","text":"Նույնիսկ պինդ նյութի մասնիկների միջև կան ազատ տարածություններ։"},{"key":"B","text":"Երկաթը բարձր ջերմաստիճանում դադարում է նյութ լինելուց։"},{"key":"C","text":"Գազը վերածվում է երկաթի։"},{"key":"D","text":"Պինդ մարմինները կազմված չեն մասնիկներից։"}],"answer":"A","stimulus":{}},{"code":"PHY7-U02-S02-I04","version":3,"prompt":"Պղնձե լարը տաքացնելիս երկարում է, իսկ սառչելիս վերադառնում է սկզբնական երկարությանը։ Ո՞ր մասնիկային բացատրությունն է ճիշտ։","options":[{"key":"A","text":"Տաքացնելիս պղնձի յուրաքանչյուր մասնիկ անընդհատ մեծանում է։"},{"key":"B","text":"Տաքացնելիս նոր պղնձի մասնիկներ են առաջանում։"},{"key":"C","text":"Տաքացնելիս պղինձը կորցնում է զանգվածը։"},{"key":"D","text":"Տաքացնելիս մասնիկների միջև միջին հեռավորությունը մեծանում է։"}],"answer":"D","stimulus":{}},{"code":"PHY7-U02-S02-I05","version":1,"prompt":"Նկարի ա մասում հեղուկի ծավալը բեռի ազդեցությամբ գրեթե չի փոխվում, իսկ բ մասում գազի ծավալը փոքրանում է։ Համեմատությունը ո՞ր մասնիկային բացատրությանն է համապատասխանում։","options":[{"key":"A","text":"Գազի մասնիկների միջև տարածություններն ավելի մեծ են, և սեղմելիս դրանք կարող են փոքրանալ։"},{"key":"B","text":"Գազը հոծ է՝ առանց մասնիկների միջև տարածությունների, իսկ բեռը հոծ նյութն է փոքրացնում։"},{"key":"C","text":"Սեղմելիս գազի մի շարք մասնիկներ անհետանում են, և այդ պատճառով ծավալը փոքրանում է։"},{"key":"D","text":"Բեռը գազի մասնիկները վերածում է հեղուկի մասնիկների, ուստի ծավալը փոքրանում է։"}],"answer":"A","stimulus":{"url":"https://www.haiedu.am/assets/textbook/physics7-2023/figure-22.png","kind":"image","altHy":"Նկար 22. ա՝ հեղուկով, բ՝ գազով գլաններ՝ առանց բեռի և բեռի ազդեցության տակ։","source":{"figure":22,"sha256":"6b52815c60f5d3324d6c5c44c9896511d7a3e7adc1827edf1e5981c1adf9860b","edition":"Physics 7 (2023)","printedPage":24}}},{"code":"PHY7-U02-S02-I06","version":1,"prompt":"Նկարում տաքացնելուց հետո ջրի մակարդակը և փակ գազով անոթի մխոցի դիրքը բարձրացել են։ Ո՞ր բացատրությունն է համապատասխանում ջրի և գազի ծավալների մեծացմանը՝ մասնիկային մոդելի շրջանակում։","options":[{"key":"A","text":"Տաքացնելիս ջրի և գազի առանձին մասնիկների չափերը մեծանում են։"},{"key":"B","text":"Տաքացնելիս մասնիկների միջև միջին հեռավորությունները մեծանում են, և նույն նյութն ավելի մեծ ծավալ է զբաղեցնում։"},{"key":"C","text":"Տաքացնելիս երկու անոթներում էլ նոր մասնիկներ են առաջանում։"},{"key":"D","text":"Ջուրը և գազը հոծ միջավայրեր են՝ առանց մասնիկների միջև տարածությունների, և հենց հոծ նյութն է մեծանում։"}],"answer":"B","stimulus":{"url":"https://www.haiedu.am/assets/textbook/physics7-2023/figure-24.png","kind":"image","altHy":"Նկար 24. ջրով անոթների և փակ գազով անոթների զույգեր՝ մինչև տաքացնելը և տաքացնելու ընթացքում։ Պահպանված են ջրի, գազի և մխոցի նշումները։","source":{"figure":24,"sha256":"915b9c67b2e20aad3412a34385c5b3b3644873f705824df5c96e26875f89ac94","edition":"Physics 7 (2023)","printedPage":25}}},{"code":"PHY7-U02-S02-I07","version":1,"prompt":"Տաքացնելիս հենարանների միջև ամրացված պղնձե լարն ավելի է կախվում, իսկ սառչելիս վերադառնում է սկզբնական տեսքին։ Սովորողն ասում է. «Այս նկարը ցույց է տալիս, որ պղնձի յուրաքանչյուր մասնիկը մեծացել է»։ Ո՞ր պատասխանն է հիմնավորված։","options":[{"key":"A","text":"Այո՛, լարի երկարության մեծացումը ուղղակի չափում է առանձին մասնիկների չափերի մեծացումը։"},{"key":"B","text":"Լարը երկարել է, քանի որ տաքացնելիս նրա ներսում նոր պղնձի մասնիկներ են առաջացել։"},{"key":"C","text":"Նկարում դիտվում է լարի ձևի փոփոխությունը, ոչ թե առանձին մասնիկների չափը։ Մասնիկային մոդելում երկարացումը կապվում է միջին հեռավորությունների մեծացման հետ։"},{"key":"D","text":"Լարը հոծ է՝ առանց մասնիկների միջև տարածությունների, ուստի երկարացումը հնարավոր է միայն հոծ նյութի մեծացմամբ։"}],"answer":"C","stimulus":{"url":"https://www.haiedu.am/assets/textbook/physics7-2023/figure-23.png","kind":"image","altHy":"Նկար 23. երկու հենարանի միջև ամրացված լար և դրա տակ գտնվող այրիչ։","source":{"figure":23,"sha256":"538d24ea12db1075815db91bdb6a2fb14f6c2ad6b8a5ba086eb754516aa228d8","edition":"Physics 7 (2023)","printedPage":25}}},{"code":"PHY7-U02-S02-I08","version":1,"prompt":"Օդով ներարկիչի ծայրը փակել են։ Մխոցը ներս են սեղմում, ապա թույլ տալիս, որ այն վերադառնա սկզբնական դիրքին։ Օդ չի ավելացվում և չի կորչում, իսկ ջերմաստիճանը չի փոխվում։ Ինչպե՞ս է մասնիկային մոդելը բացատրում օդի ծավալի փոքրացումը և հետո վերականգնումը։","options":[{"key":"A","text":"Սեղմելիս օդի մասնիկները անհետանում են, իսկ ծավալը վերականգնելիս նորից առաջանում։"},{"key":"B","text":"Օդը հոծ է՝ առանց մասնիկների միջև տարածությունների, և հոծ նյութը փոքրանում ու հետո մեծանում է։"},{"key":"C","text":"Սեղմելիս օդի մասնիկները դառնում են հեղուկի մասնիկներ, իսկ հետո նորից վերածվում օդի մասնիկների։"},{"key":"D","text":"Սեղմելիս մասնիկների միջև միջին հեռավորությունները փոքրանում են, իսկ սկզբնական ծավալը վերականգնելիս՝ մեծանում։ Մասնիկների քանակն ու ինքնությունը պահպանվում են։"}],"answer":"D","stimulus":{}},{"code":"PHY7-U02-S02-I09","version":2,"prompt":"Պղնձե լարն անզեն աչքով հոծ (հավասարաչափ ամբողջական) է թվում. առանձին մասնիկներ և դրանց միջև եղած տարածություններ չենք նկատում։ Ինչո՞ւ այս դիտումը չի հերքում նյութի մասնիկային կառուցվածքը։","options":[{"key":"A","text":"Պղինձը հոծ նյութ է. մասնիկներից կազմված են միայն հեղուկներն ու գազերը։"},{"key":"B","text":"Մասնիկներն ու դրանց միջև եղած տարածություններն այնքան փոքր են, որ անզեն աչքով չեն կարող զանազանվել։"},{"key":"C","text":"Պղնձի մասնիկները հանգստի վիճակում միաձուլվում են մեկ ամբողջության։"},{"key":"D","text":"Պղնձի մասնիկներն առաջանում են միայն ջերմաստիճանի փոփոխության դեպքում։"}],"answer":"B","stimulus":{}},{"code":"PHY7-U02-S02-I10","version":1,"prompt":"Նկարում պատկերված պղնձե լարը տաքացնելիս երկարում է։ Մեկ այլ փորձով փակ ներարկիչի օդը սեղմում են՝ առանց օդի արտահոսքի։ Ո՞ր զույգ բացատրությունն է համապատասխանում երկու փորձերին՝ պարզ մասնիկային մոդելի շրջանակում։","options":[{"key":"A","text":"Լարում նոր մասնիկներ են առաջանում, իսկ ներարկիչի օդի որոշ մասնիկներ անհետանում են։"},{"key":"B","text":"Լարի առանձին մասնիկները մեծանում են, իսկ օդի մասնիկների միջև հեռավորությունները փոքրանում են։"},{"key":"C","text":"Երկու նյութերն էլ հոծ են. մեկը մեծանում է, մյուսը՝ փոքրանում՝ առանց մասնիկների միջև տարածությունների։"},{"key":"D","text":"Լարում մասնիկների միջև միջին հեռավորությունները մեծանում են, իսկ օդում՝ փոքրանում. երկու դեպքում էլ մասնիկների քանակը պահպանվում է։"}],"answer":"D","stimulus":{"url":"https://www.haiedu.am/assets/textbook/physics7-2023/figure-23.png","kind":"image","altHy":"Նկար 23. երկու հենարանի միջև ամրացված պղնձե լար և դրա տակ գտնվող այրիչ։","source":{"figure":23,"sha256":"538d24ea12db1075815db91bdb6a2fb14f6c2ad6b8a5ba086eb754516aa228d8","edition":"Physics 7 (2023)","printedPage":25}}},{"code":"PHY7-U02-S02-I11","version":1,"prompt":"Նկարի ա մասում հեղուկը բեռի ազդեցությամբ գրեթե չի սեղմվում։ Սովորողը եզրակացնում է. «Ուրեմն հեղուկի մասնիկների միջև տարածություններ չկան»։ Ո՞ր պատասխանն է ճիշտ գնահատում այդ եզրակացությունը։","options":[{"key":"A","text":"Գրեթե չսեղմվելը չի նշանակում տարածությունների բացակայություն. հեղուկի մասնիկների միջև տարածությունների մասին վկայում են նաև լուծման և խառնման փորձերը։"},{"key":"B","text":"Եզրակացությունը ճիշտ է. հեղուկները հոծ են, իսկ մասնիկների միջև տարածություններ կան միայն գազերում։"},{"key":"C","text":"Հեղուկի մասնիկները սեղմելիս միաձուլվում են մեկ մասնիկի, ուստի նրա ծավալը գրեթե չի փոխվում։"},{"key":"D","text":"Աղը ջրում լուծելիս նրա մասնիկներն անհետանում են, ուստի լուծման փորձը նույնպես հաստատում է հեղուկի հոծ լինելը։"}],"answer":"A","stimulus":{"url":"https://www.haiedu.am/assets/textbook/physics7-2023/figure-22.png","kind":"image","altHy":"Նկար 22. ա՝ հեղուկով, բ՝ գազով գլաններ՝ առանց բեռի և բեռի ազդեցության տակ։","source":{"figure":22,"sha256":"6b52815c60f5d3324d6c5c44c9896511d7a3e7adc1827edf1e5981c1adf9860b","edition":"Physics 7 (2023)","printedPage":24}}},{"code":"PHY7-U02-S02-I12","version":1,"prompt":"Երկու ներարկիչներում սկզբում նույն քանակի օդ կա։ Առաջինի ծայրը փակ է. մխոցը ներս են սեղմում՝ առանց օդի արտահոսքի։ Երկրորդի ծայրը բաց է. մխոցը ներս հրելիս օդի մի մասը դուրս է գալիս։ Երկուսում էլ օդի զբաղեցրած ծավալը փոքրանում է։ Ի՞նչ տարբերություն պետք է արտացոլի մասնիկային մոդելը։","options":[{"key":"A","text":"Երկու ներարկիչում էլ մասնիկների քանակը նվազում է, քանի որ օդի զբաղեցրած ծավալը փոքրանում է։"},{"key":"B","text":"Փակ ներարկիչում օդի մասնիկները վերածվում են այլ նյութի մասնիկների, իսկ բաց ներարկիչից դրանց մի մասը դուրս է գալիս։"},{"key":"C","text":"Փակ ներարկիչում մասնիկների քանակը պահպանվում է, իսկ բաց ներարկիչում՝ նվազում, քանի որ դրանց մի մասը դուրս է գալիս։"},{"key":"D","text":"Երկու ներարկիչում էլ օդը հոծ նյութ է, ուստի ծավալի փոփոխությունը մասնիկներով բացատրել պետք չէ։"}],"answer":"C","stimulus":{}}]'::jsonb then
    raise exception '15B13C_whole_skill_comparison_stale';
