  update public.item_templates set template_version=2,updated_at=now(),generation_config=generation_config||
    jsonb_build_object('familySizeRationaleHy','Չորս հարցերը տարբերակում են անզեն աչքով տեսանելիությունը և կառուցվածքը, որակական բացատրությունը և ճշգրիտ չափումը, հեղուկի փոքր սեղմելիությունը և տարածությունների բացակայությունը, փակ և բաց համակարգերի փոփոխությունները։')
  where id=v_template.id;
  update public.items set prompt_hy='Դասագրքի փորձում 1 լ ջուրը խառնում են 1 լ սպիրտի հետ և ստանում 2 լ-ից փոքր ծավալով խառնուրդ։ Սովորողն ասում է. «Քանի որ մասնիկների միջև ազատ տարածություններ կան, խառնուրդի ծավալը պետք է լինի ճիշտ 1,5 լ»։ Ո՞ր գնահատականն է հիմնավորված։',prompt_en=null,stimulus='{}'::jsonb,
    source_reference='Գործող Ֆիզիկա 7 ծրագիր՝ Թեմա 2, պարտադիր վերջնարդյունք 1(1); Ֆիզիկա 7 (2023), Գլուխ II, §7, տպագիր էջեր 25-26, ջրի և սպիրտի խառնման փորձ',
    config=config||'{"sprint":"15B.13C","textbookLocator":"Ֆիզիկա 7 (2023), Գլուխ II, §7, տպագիր էջեր 25-26, ջրի և սպիրտի խառնման փորձ","illustrationDisposition":"verbal_task_no_illustration_needed","evidencePurposeRationaleHy":"Որակական մասնիկային բացատրությունը կիրառելիս տարբերակում է փորձով հիմնավորված համեմատությունը և չչափված ճշգրիտ թվային արժեքը։","wholeSkillReviewPolicy":"haiedu-whole-skill-review-v1","wholeSkillReviewEvidence":"docs/chapter-ii-s02-whole-bank-review.md","wholeSkillReviewDisposition":"new_reasoning_coverage","humanReviewStatus":"pending","technicalQaStatus":"pending","learnerVisible":false}'::jsonb,
    variant_parameters=variant_parameters||'{"focusKey":"qualitative_explanation_vs_exact_measurement"}'::jsonb,
    version_no=2,status='review',review_status='needs_review',last_reviewed_at=null,last_reviewed_by=null,updated_at=now()
  where id=v_item.id;
  update public.item_options o set content_hy=p.text,content_en=null
  from (values ('A','Ճիշտ է. մասնիկների միջև ազատ տարածությունների գոյությունը բավարար է հենց 1,5 լ ծավալ ստանալու մասին եզրակացնելու համար։'),('B','Սխալ է. հեղուկներում մասնիկների միջև ազատ տարածություններ չկան, ուստի խառնուրդի ծավալը պետք է լինի 2 լ։'),('C','Սխալ է. խառնելիս սպիրտի մասնիկներն անհետանում են, ուստի մնում է միայն ջուրը՝ ճիշտ 1 լ ծավալով։'),('D','Մոդելը բացատրում է, թե ինչու է խառնուրդի ծավալը 2 լ-ից փոքր, բայց 1,5 լ թիվը միայն այդ բացատրությունից չի հետևում. ճշգրիտ ծավալը պետք է չափել։')) p(key,text)
  where o.item_id=v_item.id and o.option_key=p.key;
  update public.item_answer_keys set feedback_code='qualitative_explanation_vs_exact_measurement',updated_at=now() where item_id=v_item.id;
  update public.item_misconception_mappings m set misconception_id=mc.id,mapping_note=p.note
  from (values ('A','qualitative_model_implies_exact_volume','Որակական բացատրությունից առանց չափման ստացվում է չհիմնավորված ճշգրիտ թվային արժեք։'),('B','matter_as_continuous','Ժխտվում են հեղուկի մասնիկների միջև ազատ տարածությունները։'),('C','particle_identity_or_count_changes','Խառնման ընթացքում սպիրտի մասնիկների անհետացում է ենթադրվում։')) p(key,code,note)
  join public.misconceptions mc on mc.skill_id=v_item.skill_id and mc.code=p.code
  where m.item_id=v_item.id and m.response_key=p.key;
  update public.items i set variant_fingerprint=md5(i.skill_id::text||'|'||lower(regexp_replace(i.prompt_hy,'\s+',' ','g'))||'|'||
    (select answer::text from public.item_answer_keys where item_id=i.id)||'|'||
    (select jsonb_agg(jsonb_build_object('optionKey',option_key,'contentHy',content_hy) order by display_order,option_key)::text from public.item_options where item_id=i.id))
  where i.id=v_item.id;
  insert into public.item_versions(item_id,version_no,snapshot,change_summary,created_by)
  select i.id,2,jsonb_build_object('item',to_jsonb(i),
    'options',(select jsonb_agg(to_jsonb(o) order by o.display_order,o.option_key) from public.item_options o where o.item_id=i.id),
    'answerKey',(select to_jsonb(k) from public.item_answer_keys k where k.item_id=i.id),
    'misconceptions',(select jsonb_agg(jsonb_build_object('responseKey',m.response_key,'code',mc.code,'mappingNote',m.mapping_note) order by m.response_key)
      from public.item_misconception_mappings m join public.misconceptions mc on mc.id=m.misconception_id where m.item_id=i.id)),
    '15B.13C. Ամբողջ S02 բանկի համեմատությունից հետո կրկնվող տաքացում/սեղմում առաջադրանքը փոխարինվել է որակական բացատրության և ճշգրիտ չափման տարբերակմամբ։ Նոր տարբերակը և նոր թյուր պատկերացումը պահանջում են մարդկային հաստատում։',null
  from public.items i where i.id=v_item.id;
  if (select count(*) from public.item_options where item_id=v_item.id)<>4
     or (select answer from public.item_answer_keys where item_id=v_item.id)<>'"D"'::jsonb
     or (select count(*) from public.item_misconception_mappings where item_id=v_item.id)<>3 then
    raise exception '15B13C_revised_content_incomplete';
  end if;
end $revision$;
